export const meta = {
  name: 'summarize-first-lines',
  description: 'Each of three agents reads one txt file and summarizes its first line',
  phases: [{ title: 'Summarize' }],
}

const files = ['alpha.txt', 'beta.txt', 'gamma.txt']
const SCHEMA = {
  type: 'object',
  properties: {
    file: { type: 'string' },
    first_line: { type: 'string' },
    summary: { type: 'string' },
  },
  required: ['file', 'first_line', 'summary'],
}

const results = await parallel(files.map(f => () =>
  agent(
    `Read the file "${f}" in the current working directory using the Read tool. Do NOT modify it. Report back its exact first line, and a one-sentence summary of that first line.`,
    { label: `read:${f}`, phase: 'Summarize', schema: SCHEMA }
  )
))

return results.filter(Boolean)

